package com.neighbormarket.service;
import com.neighbormarket.domain.*;import com.neighbormarket.mapper.*;import org.junit.jupiter.api.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class ExchangeServiceTest {
 ItemMapper items=mock(ItemMapper.class);AppUserMapper users=mock(AppUserMapper.class);PickupSlotMapper slots=mock(PickupSlotMapper.class);ItemInterestMapper interests=mock(ItemInterestMapper.class);HandoverMapper handovers=mock(HandoverMapper.class);ItemCommentMapper comments=mock(ItemCommentMapper.class);ExchangeService service=new ExchangeService(items,users,slots,interests,handovers,comments);
 @BeforeAll static void init(){com.baomidou.mybatisplus.core.metadata.TableInfoHelper.initTableInfo(new org.apache.ibatis.builder.MapperBuilderAssistant(new com.baomidou.mybatisplus.core.MybatisConfiguration(),"test"),Item.class);com.baomidou.mybatisplus.core.metadata.TableInfoHelper.initTableInfo(new org.apache.ibatis.builder.MapperBuilderAssistant(new com.baomidou.mybatisplus.core.MybatisConfiguration(),"test-h"),Handover.class);com.baomidou.mybatisplus.core.metadata.TableInfoHelper.initTableInfo(new org.apache.ibatis.builder.MapperBuilderAssistant(new com.baomidou.mybatisplus.core.MybatisConfiguration(),"test-i"),ItemInterest.class);com.baomidou.mybatisplus.core.metadata.TableInfoHelper.initTableInfo(new org.apache.ibatis.builder.MapperBuilderAssistant(new com.baomidou.mybatisplus.core.MybatisConfiguration(),"test-s"),PickupSlot.class);}
 @Test void concurrentLoserCannotCreateSecondHandover(){when(users.selectOne(any())).thenReturn(user(1,"a"));when(interests.selectById(8L)).thenReturn(interest(8,5,2,7));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));when(slots.selectById(7L)).thenReturn(slot(7,5));when(items.update(isNull(),any())).thenReturn(0);assertStatus(HttpStatus.CONFLICT,()->service.confirm(8L,"a"));verify(handovers,never()).insert(any(Handover.class));}
 @Test void failedHandoverInsertStopsConfirmation(){prepareConfirmation();when(items.update(isNull(),any())).thenReturn(1);when(handovers.insert(any(Handover.class))).thenReturn(0);assertStatus(HttpStatus.CONFLICT,()->service.confirm(8L,"a"));verify(interests,never()).update(isNull(),any());}
 @Test void failedHandoverLinkStopsConfirmation(){prepareConfirmation();when(items.update(isNull(),any())).thenReturn(1,0);insertHandoverWithId();assertStatus(HttpStatus.CONFLICT,()->service.confirm(8L,"a"));verify(interests,never()).update(isNull(),any());}
 @Test void failedInterestTransitionStopsConfirmation(){prepareConfirmation();when(items.update(isNull(),any())).thenReturn(1,1);insertHandoverWithId();when(interests.update(isNull(),any())).thenReturn(0);assertStatus(HttpStatus.CONFLICT,()->service.confirm(8L,"a"));}
 @Test void nonPublisherCannotConfirm(){when(users.selectOne(any())).thenReturn(user(3,"c"));when(interests.selectById(8L)).thenReturn(interest(8,5,2,7));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));assertStatus(HttpStatus.FORBIDDEN,()->service.confirm(8L,"c"));}
 @Test void publisherCannotWantOwnItem(){when(users.selectOne(any())).thenReturn(user(1,"a"));when(items.selectByIdForUpdate(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));assertStatus(HttpStatus.FORBIDDEN,()->service.want(5L,7L,0L,"a"));}
 @Test void staleItemVersionCannotCreateInterest(){when(users.selectOne(any())).thenReturn(user(2,"b"));Item changed=item(5,1,ItemStatus.AVAILABLE);changed.setVersion(1L);when(items.selectByIdForUpdate(5L)).thenReturn(changed);assertStatus(HttpStatus.CONFLICT,()->service.want(5L,7L,0L,"b"));verify(interests,never()).upsertWaiting(anyLong(),anyLong(),anyLong(),any());}
 @Test void inactiveHistoricalSlotCannotReceiveNewInterest(){when(users.selectOne(any())).thenReturn(user(2,"b"));when(items.selectByIdForUpdate(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));PickupSlot historical=slot(7,5);historical.setActive(false);when(slots.selectById(7L)).thenReturn(historical);assertStatus(HttpStatus.CONFLICT,()->service.want(5L,7L,0L,"b"));verify(interests,never()).insert(any(ItemInterest.class));}
 @Test void wantUsesAtomicUpsertAndReturnsPersistedInterest(){AppUser applicant=user(2,"b");Item available=item(5,1,ItemStatus.AVAILABLE);PickupSlot active=slot(7,5);ItemInterest waiting=interest(8,5,2,7);when(users.selectOne(any())).thenReturn(applicant);when(items.selectByIdForUpdate(5L)).thenReturn(available);when(slots.selectById(7L)).thenReturn(active);when(interests.selectByItemAndUserForUpdate(5L,2L)).thenReturn(waiting);when(users.selectById(2L)).thenReturn(applicant);var result=service.want(5L,7L,0L,"b");assertEquals(8L,result.id());verify(interests).upsertWaiting(eq(5L),eq(2L),eq(7L),any());verify(interests).selectByItemAndUserForUpdate(5L,2L);verify(interests,never()).insert(any(ItemInterest.class));verify(interests,never()).updateById(any(ItemInterest.class));}
 @Test void atomicUpsertCannotResetConfirmedInterest(){AppUser applicant=user(2,"b");when(users.selectOne(any())).thenReturn(applicant);when(items.selectByIdForUpdate(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));when(slots.selectById(7L)).thenReturn(slot(7,5));ItemInterest confirmed=interest(8,5,2,7);confirmed.setStatus(InterestStatus.CONFIRMED);when(interests.selectByItemAndUserForUpdate(5L,2L)).thenReturn(confirmed);assertStatus(HttpStatus.CONFLICT,()->service.want(5L,7L,0L,"b"));verify(interests).upsertWaiting(eq(5L),eq(2L),eq(7L),any());verify(interests,never()).insert(any(ItemInterest.class));verify(interests,never()).updateById(any(ItemInterest.class));}
 @Test void cancellingInterestChecksAffectedRows(){when(users.selectOne(any())).thenReturn(user(2,"b"));when(interests.selectOne(any())).thenReturn(interest(8,5,2,7));when(interests.update(isNull(),any())).thenReturn(0);assertStatus(HttpStatus.CONFLICT,()->service.cancelInterest(5L,"b"));verify(users,never()).selectById(anyLong());}
 @Test void reconfigureDeactivatesOldSlotsWithoutDeletingHistory(){when(users.selectOne(any())).thenReturn(user(1,"a"));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));when(interests.selectWaitingIdForUpdate(5L)).thenReturn(null);when(slots.selectList(any())).thenReturn(java.util.List.of());var start=java.time.LocalDateTime.now().plusDays(2);service.configure(5L,"new gate",java.util.List.of(new ExchangeService.SlotInput(start,start.plusHours(1))),"a");verify(slots,never()).delete(any());var updateCaptor=org.mockito.ArgumentCaptor.forClass(com.baomidou.mybatisplus.core.conditions.Wrapper.class);verify(slots).update(isNull(),updateCaptor.capture());var update=(com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<PickupSlot>)updateCaptor.getValue();assertTrue(update.getSqlSet().contains("active"));verify(slots).insert(org.mockito.Mockito.<PickupSlot>argThat(s->Boolean.TRUE.equals(s.getActive())&&s.getItemId().equals(5L)));}
 @Test void completedItemCommentIsReadOnly(){when(users.selectOne(any())).thenReturn(user(2,"b"));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.COMPLETED));assertStatus(HttpStatus.CONFLICT,()->service.comment(5L,"hello","b"));verify(comments,never()).insert(any(ItemComment.class));}
 @Test void publisherCanReplyToTopLevelAndContentIsTrimmed(){when(users.selectOne(any())).thenReturn(user(1,"a"));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));when(comments.selectById(10L)).thenReturn(comment(10,5,null));when(users.selectById(1L)).thenReturn(user(1,"a"));var result=service.reply(5L,10L,"  reply  ","a");assertEquals(10L,result.parentId());assertEquals("reply",result.content());verify(comments).insert(org.mockito.ArgumentMatchers.<ItemComment>argThat(c->c.getParentId().equals(10L)&&c.getItemId().equals(5L)));}
 @Test void nonPublisherCannotReply(){when(users.selectOne(any())).thenReturn(user(2,"b"));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));assertStatus(HttpStatus.FORBIDDEN,()->service.reply(5L,10L,"reply","b"));verify(comments,never()).insert(any(ItemComment.class));}
 @Test void crossItemReplyIsRejected(){when(users.selectOne(any())).thenReturn(user(1,"a"));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));when(comments.selectById(10L)).thenReturn(comment(10,6,null));assertStatus(HttpStatus.BAD_REQUEST,()->service.reply(5L,10L,"reply","a"));}
 @Test void replyToReplyIsRejected(){when(users.selectOne(any())).thenReturn(user(1,"a"));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));when(comments.selectById(11L)).thenReturn(comment(11,5,10L));assertStatus(HttpStatus.BAD_REQUEST,()->service.reply(5L,11L,"nested","a"));}
 @Test void unrelatedThirdUserCannotReadCancelOrCompleteHandover(){AppUser outsider=user(3,"test_outsider");Handover active=handover(20,5,1,2,HandoverStatus.ACTIVE);when(users.selectOne(any())).thenReturn(outsider);when(handovers.selectViewById(20L)).thenReturn(handoverView(active));when(handovers.selectById(20L)).thenReturn(active);assertStatus(HttpStatus.FORBIDDEN,()->service.handover(20L,"test_outsider"));assertStatus(HttpStatus.FORBIDDEN,()->service.cancelHandover(20L,"test_outsider"));assertStatus(HttpStatus.FORBIDDEN,()->service.complete(20L,"test_outsider"));verify(handovers,never()).update(isNull(),any());verify(items,never()).update(isNull(),any());}
 @Test void cancellationClearsCurrentHandoverReference(){Handover active=handover(20,5,1,2,HandoverStatus.ACTIVE),cancelled=handover(20,5,1,2,HandoverStatus.CANCELLED);when(users.selectOne(any())).thenReturn(user(2,"b"));when(handovers.selectById(20L)).thenReturn(active,cancelled);when(handovers.update(isNull(),any())).thenReturn(1);when(items.update(isNull(),any())).thenReturn(1);when(interests.update(isNull(),any())).thenReturn(1);Item restored=item(5,1,ItemStatus.AVAILABLE);restored.setCurrentHandoverId(null);when(items.selectById(5L)).thenReturn(restored);when(users.selectById(anyLong())).thenReturn(user(1,"a"));service.cancelHandover(20L,"b");var captor=org.mockito.ArgumentCaptor.forClass(com.baomidou.mybatisplus.core.conditions.Wrapper.class);verify(items).update(isNull(),captor.capture());var update=(com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<Item>)captor.getValue();assertTrue(update.getSqlSet().contains("current_handover_id"));assertNull(restored.getCurrentHandoverId());}
 @Test void cancellationChecksConfirmedInterestTransition(){when(users.selectOne(any())).thenReturn(user(2,"b"));when(handovers.selectById(20L)).thenReturn(handover(20,5,1,2,HandoverStatus.ACTIVE));when(handovers.update(isNull(),any())).thenReturn(1);when(items.update(isNull(),any())).thenReturn(1);when(interests.update(isNull(),any())).thenReturn(0);assertStatus(HttpStatus.CONFLICT,()->service.cancelHandover(20L,"b"));}
 @Test void completionKeepsCurrentHandoverPointingAtCompletedRecord(){Handover active=handover(21,6,1,2,HandoverStatus.ACTIVE),completed=handover(21,6,1,2,HandoverStatus.COMPLETED);when(users.selectOne(any())).thenReturn(user(1,"a"));when(handovers.selectById(21L)).thenReturn(active,completed);when(handovers.update(isNull(),any())).thenReturn(1);when(items.update(isNull(),any())).thenReturn(1);Item done=item(6,1,ItemStatus.COMPLETED);done.setCurrentHandoverId(21L);when(items.selectById(6L)).thenReturn(done);when(users.selectById(anyLong())).thenReturn(user(1,"a"));service.complete(21L,"a");var captor=org.mockito.ArgumentCaptor.forClass(com.baomidou.mybatisplus.core.conditions.Wrapper.class);verify(items).update(isNull(),captor.capture());var update=(com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<Item>)captor.getValue();assertTrue(update.getSqlSegment().contains("current_handover_id"));assertFalse(update.getSqlSet().contains("current_handover_id"));assertEquals(21L,done.getCurrentHandoverId());} @Test void completedItemCannotBeReplied(){when(users.selectOne(any())).thenReturn(user(1,"a"));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.COMPLETED));assertStatus(HttpStatus.CONFLICT,()->service.reply(5L,10L,"reply","a"));}
 static void assertStatus(HttpStatus status,Executable x){var e=assertThrows(ResponseStatusException.class,x::run);assertEquals(status,e.getStatusCode());}interface Executable{void run();}
 void prepareConfirmation(){when(users.selectOne(any())).thenReturn(user(1,"a"));when(interests.selectById(8L)).thenReturn(interest(8,5,2,7));when(items.selectById(5L)).thenReturn(item(5,1,ItemStatus.AVAILABLE));when(slots.selectById(7L)).thenReturn(slot(7,5));}
 void insertHandoverWithId(){when(handovers.insert(any(Handover.class))).thenAnswer(invocation->{Handover handover=invocation.getArgument(0);handover.setId(20L);return 1;});}
 static AppUser user(long id,String name){AppUser u=new AppUser();u.setId(id);u.setUsername(name);u.setNickname(name);return u;}static Item item(long id,long owner,ItemStatus status){Item i=new Item();i.setId(id);i.setPublisherId(owner);i.setStatus(status);i.setPickupLocation("gate");i.setVersion(0L);return i;}static ItemInterest interest(long id,long item,long user,long slot){ItemInterest i=new ItemInterest();i.setId(id);i.setItemId(item);i.setUserId(user);i.setSlotId(slot);i.setStatus(InterestStatus.WAITING);return i;}static PickupSlot slot(long id,long item){PickupSlot s=new PickupSlot();s.setId(id);s.setItemId(item);s.setStartAt(java.time.LocalDateTime.now().plusDays(1));s.setEndAt(java.time.LocalDateTime.now().plusDays(1).plusHours(1));s.setActive(true);return s;}static Handover handover(long id,long item,long publisher,long recipient,HandoverStatus status){Handover h=new Handover();h.setId(id);h.setItemId(item);h.setPublisherId(publisher);h.setRecipientId(recipient);h.setInterestId(8L);h.setStatus(status);h.setStartAt(java.time.LocalDateTime.now().plusDays(1));h.setEndAt(java.time.LocalDateTime.now().plusDays(1).plusHours(1));h.setLocationSnapshot("gate");return h;}static HandoverViewRow handoverView(Handover h){HandoverViewRow row=new HandoverViewRow();row.setId(h.getId());row.setItemId(h.getItemId());row.setPublisherId(h.getPublisherId());row.setRecipientId(h.getRecipientId());row.setInterestId(h.getInterestId());row.setStatus(h.getStatus());row.setStartAt(h.getStartAt());row.setEndAt(h.getEndAt());row.setLocationSnapshot(h.getLocationSnapshot());row.setItemTitle("item");row.setPublisherName("publisher");row.setRecipientName("recipient");return row;}static ItemComment comment(long id,long item,Long parent){ItemComment c=new ItemComment();c.setId(id);c.setItemId(item);c.setParentId(parent);c.setContent("q");c.setCreatedAt(java.time.LocalDateTime.now());return c;}
}
